function stockLineChart(input){
 const values=(input||[]).map(x=>Number(typeof x==='object'?x.value:x)).filter(Number.isFinite);
 if(!values.length)return '<div class="empty">Wykres pojawi się po pierwszym dniu notowań.</div>';
 if(values.length===1)values.unshift(values[0]);
 const width=640,height=170,pad=12,min=Math.min(...values),max=Math.max(...values),range=Math.max(1,max-min);
 const points=values.map((v,i)=>(pad+i/(values.length-1)*(width-pad*2)).toFixed(1)+','+(height-pad-(v-min)/range*(height-pad*2)).toFixed(1)).join(' ');
 const change=values[0]?((values.at(-1)-values[0])/values[0])*100:0;
 return '<div class="stock-chart-shell '+(change>=0?'up':'down')+'"><div class="stock-chart-meta"><span>HISTORIA WYCENY</span><b>'+(change>=0?'+':'')+change.toFixed(2)+'%</b></div><svg class="stock-line-chart" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Wykres historycznej wyceny"><line x1="0" y1="'+(height/2)+'" x2="'+width+'" y2="'+(height/2)+'" class="stock-chart-grid"/><polyline points="'+points+'" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="'+(pad+(values.length-1)/(values.length-1)*(width-pad*2))+'" cy="'+(height-pad-(values.at(-1)-min)/range*(height-pad*2))+'" r="4" fill="currentColor"/></svg><div class="stock-chart-foot"><span>Min. '+money(min)+'</span><span>Aktualnie '+money(values.at(-1))+'</span></div></div>';
}
